import unittest
from envconfig import load
class Required(unittest.TestCase):
 def test_defaults(self):self.assertEqual(load(["A=one"]),{"A":"one"})
 def test_empty_counts(self):self.assertEqual(load(["A="],required_keys=("A",)),{"A":""})
 def test_missing(self):
  with self.assertRaises(ValueError):load(["A=one"],required_keys=("A","B"))
 def test_case_sensitive(self):
  with self.assertRaises(ValueError):load(["A=one"],required_keys=("a",))
 def test_iterator(self):self.assertEqual(load(iter(["A=1","B=2"]),required_keys=iter(["A","B"])),{"A":"1","B":"2"})

from envsyntax import parse_entry

def load(lines, *, reject_duplicates=False, required_keys=()):
    config = {}
    for line in lines:
        entry = parse_entry(line)
        if entry is None:
            continue
        key, value = entry
        if reject_duplicates and key in config:
            raise ValueError(f"duplicate key: {key}")
        config[key] = value
    for key in required_keys:
        if key not in config:
            raise ValueError(f"missing required key: {key}")
    return config
